'use strict';
const topics=[
 {name:'Электролитическая диссоциация',short:'Растворы и ионы',desc:'Почему одни растворы проводят ток, а другие — нет?',goal:'Объяснять электропроводность растворов и диссоциацию электролитов.',code:'9.4.1.1 · 9.4.1.2',title:'Что покажет датчик?',intro:'В школьной лаборатории исследовали три образца при одинаковой температуре. Для каждого измерения использовали чистые электроды и одинаковое напряжение. Показания датчика приведены в условных единицах.',table:'<table><caption>Результаты учебного опыта</caption><thead><tr><th>Образец</th><th>Показание</th></tr></thead><tbody><tr><td>Дистиллированная вода</td><td>0,2</td></tr><tr><td>Раствор сахара</td><td>0,3</td></tr><tr><td>Раствор NaCl</td><td>8,4</td></tr></tbody></table>',note:'Числа — модельные данные для задания. Сравниваются водные растворы.',tip:'Повторите, какие частицы переносят заряд в растворе и как записывается диссоциация солей.'},
 {name:'Периодический закон',short:'Закономерности элементов',desc:'Как строение атома помогает объяснить свойства металлов?',goal:'Сравнивать свойства металлов I и II групп, составлять уравнения реакций.',code:'9.2.1.3',title:'Металлы одной группы',intro:'Учащиеся анализируют данные о трёх щелочных металлах. Внешний энергетический уровень каждого атома содержит один электрон. В таблице показано число занятых электронных слоёв.',table:'<table><thead><tr><th>Элемент</th><th>Электронные слои</th></tr></thead><tbody><tr><td>Литий, Li</td><td>2</td></tr><tr><td>Натрий, Na</td><td>3</td></tr><tr><td>Калий, K</td><td>4</td></tr></tbody></table>',note:'Задание на анализ данных. Реакции щелочных металлов с водой не предназначены для самостоятельного опыта.',tip:'Проследите цепочку: больше электронных слоёв → внешний электрон дальше от ядра → легче отдаётся.'},
 {name:'Зависимость свойств от строения',short:'Строение и свойства',desc:'Выбираем материал по его химическому строению.',goal:'Объяснять свойства веществ на основе типа связи и строения кристаллической решётки.',code:'Строение вещества · химическая связь',title:'Материал для электрода',intro:'Для учебной модели нужен материал, проводящий ток в твёрдом состоянии. Учащиеся сравнивают три вещества и связывают их свойства со строением.',table:'<table><thead><tr><th>Вещество</th><th>Особенность строения</th></tr></thead><tbody><tr><td>Графит</td><td>Слои атомов углерода; есть подвижные электроны</td></tr><tr><td>Алмаз</td><td>Прочная пространственная сеть связей; подвижных носителей заряда нет</td></tr><tr><td>NaCl</td><td>Ионы закреплены в узлах твёрдой решётки</td></tr></tbody></table>',note:'Рассматриваются чистые вещества при обычных условиях.',tip:'Различайте электроны в графите и подвижные ионы в растворах и расплавах солей.'},
 {name:'Вещества, здоровье и окружающая среда',short:'Химия и окружающая среда',desc:'Объясняем последствия горения и выбираем решения.',goal:'Определять продукты горения и объяснять экологические последствия химических процессов.',code:'8.3.1.1 · химия и жизнь',title:'Воздух рядом с котельной',intro:'Котельная сжигает топливо, содержащее углерод и примеси серы. Инженер сравнил два режима горения. Состав топлива и его расход одинаковы; менялась подача воздуха.',table:'<table><caption>Условные данные состава дымовых газов</caption><thead><tr><th>Режим</th><th>Кислород</th><th>CO</th></tr></thead><tbody><tr><td>А</td><td>Недостаток</td><td>Повышенное содержание</td></tr><tr><td>Б</td><td>Достаточная подача</td><td>Пониженное содержание</td></tr></tbody></table>',note:'Содержание CO — отдельный показатель. Оно не характеризует все загрязняющие вещества в выбросах.',tip:'Различайте CO и CO₂; связывайте SO₂ с кислотными осадками. Вывод должен опираться на измеряемый показатель.'}
];
const questions=[
 {t:0,level:'Применение',q:'Почему датчик показывает наибольшее значение для раствора NaCl?',o:['В растворе движутся свободные электроны, как в металле.','В воде NaCl образует подвижные ионы Na⁺ и Cl⁻.','Молекулы воды превращаются в атомы натрия.','Любое растворённое вещество одинаково проводит ток.'],a:1,e:'NaCl диссоциирует на Na⁺ и Cl⁻. Движение этих ионов переносит электрический заряд в растворе.',errors:['В металлах заряд переносят электроны, а в растворах электролитов — ионы.','','Растворение соли не превращает воду в другой химический элемент.','Раствор сахара служит контрпримером: растворение не всегда сопровождается образованием ионов.']},
 {t:0,level:'Применение',q:'В воде полностью диссоциировало 0,10 моль NaCl. Каково суммарное количество вещества образовавшихся ионов?',o:['0,05 моль','0,10 моль','0,20 моль','0,30 моль'],a:2,e:'NaCl → Na⁺ + Cl⁻. Из 0,10 моль соли получается 0,10 моль Na⁺ и 0,10 моль Cl⁻; всего 0,20 моль ионов.',errors:['При диссоциации количество частиц увеличивается.','Учтён только один из двух видов ионов.','','Одна формульная единица NaCl даёт два иона, а не три.']},
 {t:0,level:'Анализ',q:'Какой вывод подтверждается результатами опыта?',o:['Растворение вещества в воде не всегда приводит к заметной электропроводности.','Все прозрачные растворы проводят ток одинаково.','Сахар в воде образует столько же ионов, сколько NaCl.','В растворе NaCl ток переносят только молекулы воды.'],a:0,e:'Показание для сахара близко к показанию воды, а для NaCl значительно выше. Значит, сам факт растворения ещё не означает появления большого числа подвижных ионов.',errors:['','Прозрачность не определяет количество подвижных ионов.','Сахар растворяется преимущественно в виде молекул.','Перенос заряда в растворе NaCl обеспечивают главным образом Na⁺ и Cl⁻.']},
 {t:1,level:'Анализ',q:'У какого из этих металлов внешний электрон, как правило, легче отрывается от атома?',o:['У лития','У натрия','У всех одинаково','У калия'],a:3,e:'В группе сверху вниз увеличиваются радиус атома и экранирование ядра внутренними электронами. Поэтому калий легче отдаёт внешний электрон, чем натрий и литий.',errors:['У лития внешний электрон ближе к ядру.','Натрий отдаёт электрон легче лития, но труднее калия.','Одинаковое число внешних электронов не означает одинаковую силу их удержания.','']},
 {t:1,level:'Применение',q:'Какое уравнение правильно описывает взаимодействие натрия с водой?',o:['2Na + 2H₂O → 2NaOH + H₂','Na + H₂O → NaO + H₂','2Na + H₂O → Na₂O + H₂','Na + 2H₂O → NaOH + O₂'],a:0,e:'Образуются гидроксид натрия и водород. В уравнении 2Na + 2H₂O → 2NaOH + H₂ число атомов каждого элемента слева и справа одинаково.',errors:['','Продукт реакции — NaOH; запись NaO здесь неверна.','При взаимодействии с водой получается гидроксид, а не оксид натрия.','Выделяется водород, а не кислород; уравнение также не сбалансировано.']},
 {t:1,level:'Понимание',q:'Почему литий, натрий и калий имеют сходные химические свойства?',o:['У них одинаковое число электронных слоёв.','У них одинаковая масса атома.','У каждого один электрон на внешнем уровне.','У них одинаковый заряд ядра.'],a:2,e:'Химические свойства во многом определяются внешними электронами. У щелочных металлов на внешнем уровне один электрон.',errors:['В таблице показано разное число электронных слоёв.','Относительные атомные массы этих элементов различны.','','Заряд ядра соответствует порядковому номеру, который у каждого элемента свой.']},
 {t:2,level:'Применение',q:'Какой материал подходит для электрода по условию задачи?',o:['Алмаз — из-за высокой твёрдости.','Графит — благодаря подвижным электронам.','Твёрдый NaCl — из-за наличия любых заряженных частиц.','Все три материала одинаково подходят.'],a:1,e:'В графите есть подвижные электроны, способные переносить заряд. Твёрдость алмаза не делает его проводником, а ионы в твёрдом NaCl не могут свободно перемещаться.',errors:['Твёрдость и электропроводность — разные свойства.','','Для проводимости необходимы подвижные носители заряда.','По приведённым данным проводником в твёрдом состоянии является графит.']},
 {t:2,level:'Анализ',q:'Почему алмаз и графит, состоящие из углерода, обладают разными свойствами?',o:['Графит состоит из другого химического элемента.','У алмаза нет химических связей.','В графите все атомы превращены в ионы.','У них различаются расположение атомов и строение связей.'],a:3,e:'Алмаз и графит — аллотропные формы углерода. Пространственная сеть алмаза и слоистая структура графита определяют различие их свойств.',errors:['Оба вещества состоят из углерода.','В алмазе атомы связаны прочными ковалентными связями.','Графит не является ионным кристаллом.','']},
 {t:2,level:'Применение',q:'Что изменится при плавлении NaCl и позволит расплаву проводить ток?',o:['Ионы смогут перемещаться и переносить заряд.','Ионы полностью исчезнут.','NaCl превратится в металлический натрий.','Масса вещества станет равна нулю.'],a:0,e:'При плавлении разрушается жёсткий порядок ионной решётки. Ионы Na⁺ и Cl⁻ становятся подвижными и переносят заряд.',errors:['','Ионы сохраняются, меняется их подвижность.','Плавление — физический процесс; само по себе оно не разлагает соль на простые вещества.','Плавление не нарушает закон сохранения массы.']},
 {t:3,level:'Понимание',q:'Какое вещество обозначено формулой CO и образуется при неполном сгорании углерода?',o:['Углекислый газ','Диоксид серы','Угарный газ','Кислород'],a:2,e:'CO — монооксид углерода, или угарный газ. Он может образовываться при недостатке кислорода. Углекислый газ имеет формулу CO₂.',errors:['Углекислый газ — CO₂, а не CO.','Диоксид серы имеет формулу SO₂.','','Молекулярный кислород имеет формулу O₂.']},
 {t:3,level:'Применение',q:'Какое изменение наиболее непосредственно уменьшит образование SO₂ при сжигании такого топлива?',o:['Увеличить высоту дымовой трубы.','Использовать топливо с меньшим содержанием серы.','Окрасить корпус котельной.','Снизить подачу кислорода до недостаточной.'],a:1,e:'Сера топлива при горении образует SO₂. Снижение содержания серы уменьшает источник этого загрязнителя. Высокая труба меняет рассеивание, но не устраняет образование SO₂.',errors:['Высота трубы не уменьшает количество серы, сгорающей в топливе.','','Цвет корпуса не влияет на состав продуктов горения.','Недостаток кислорода способствует неполному сгоранию и росту CO.']},
 {t:3,level:'Оценка данных',q:'Какой вывод о режиме Б можно сделать только на основании таблицы?',o:['Все вредные вещества в выбросах отсутствуют.','Выбросы CO₂ полностью прекратились.','Режим Б устраняет образование SO₂.','Содержание CO ниже, но для оценки других выбросов нужны дополнительные измерения.'],a:3,e:'В таблице есть сведения только о CO и подаче кислорода. Снижение одного загрязнителя не доказывает отсутствие остальных.',errors:['Нулевые значения всех загрязнителей не измерялись.','В таблице нет данных о CO₂.','Содержание SO₂ в таблице не приведено.','']}
];
const app=document.getElementById('app');let session=null,screen='home',ticker=null,projector=false,teacherPoll=null;
let currentReport=null,reportFilter='',reportOnlyErrors=false,reportTarget=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){const n=document.getElementById('toast');n.textContent=s;n.style.display='block';setTimeout(()=>n.style.display='none',2800)}
function stop(){clearInterval(ticker);ticker=null;clearInterval(teacherPoll);teacherPoll=null}
function setNav(method=false){document.getElementById('nav-teacher').classList.remove('active');document.getElementById('nav-home').classList.toggle('active',!method);document.getElementById('nav-method').classList.toggle('active',method)}
function leave(fn){if(screen==='quiz'&&session&&!session.finished){if(!confirm('Завершить текущую попытку и перейти в другой раздел?'))return;stop()}fn()}
document.querySelector('.brand').onclick=e=>{e.preventDefault();leave(home)};document.getElementById('nav-home').onclick=()=>leave(home);document.getElementById('nav-method').onclick=()=>leave(method);document.getElementById('projector').onclick=()=>{projector=!projector;document.body.classList.toggle('projector',projector);document.getElementById('projector').setAttribute('aria-pressed',projector)};
function home(){stop();screen='home';setNav();app.innerHTML=`<section class="hero"><div><div class="eyebrow">Практика подготовки к МОДО</div><h1>Знать химию.<br><span class="highlight">Объяснять жизнь.</span></h1><p>Прочитайте ситуацию, исследуйте данные и выберите решение. Тренажёр помогает увидеть не только результат, но и причину ошибки.</p><div class="pills"><span class="pill">9 класс</span><span class="pill">12 вопросов</span><span class="pill">4 контекста</span><span class="pill">10 минут</span></div><div class="actions"><button class="btn primary" onclick="start('test')">Войти и начать →</button><button class="btn secondary" onclick="start('demo')">Демо для выступления</button></div><p class="small" style="margin:13px 0 0;font-size:11px">Введите имя и код занятия от учителя. Сразу после завершения вы увидите баллы и разбор ошибок.</p></div><div class="hero-art" aria-hidden="true"><div class="eyebrow">От вещества — к объяснению</div><div class="chem-map"><svg viewBox="0 0 340 195"><path d="M55 130 L160 85 L297 43 M160 85 L292 172" fill="none" stroke="#93b9ef" stroke-width="3"/><circle cx="160" cy="85" r="77" fill="none" stroke="#ffffff15" stroke-dasharray="4 7"/></svg><span class="atom one">Химия</span><span class="atom two">Na⁺</span><span class="atom three">CO</span><span class="atom four">C</span></div><div class="art-bottom"><span>01 / Контекст</span><span>02 / Решение</span><span>03 / Разбор</span></div></div></section><div class="section-title"><h2>Четыре маршрута практики</h2><p>Выберите тему для тренировки без таймера</p></div><section class="cards">${topics.map((t,i)=>`<article class="card"><span class="num">0${i+1} / 3 ЗАДАНИЯ</span><h3>${t.short}</h3><p>${t.desc}</p><button onclick="start('practice',${i})">Тренироваться ↗</button></article>`).join('')}</section><div class="source-note"><strong>Фокус ИМП:</strong> электролитическая диссоциация и периодический закон; зависимость свойств веществ от строения; влияние веществ на здоровье и окружающую среду. Основание — предоставленный фрагмент ИМП, раздел «Химия».<br>Авторская учебная версия по предоставленным материалам спецификации и образцам сайта <a href="https://taldau.edu.kz" target="_blank" rel="noopener noreferrer">taldau.edu.kz</a>. Количество вопросов и время выбраны для демонстрации; это не официальный вариант МОДО.</div>`;window.scrollTo(0,0)}
function launchSession(mode,topic){stop();const ids=mode==='demo'?[0,3,6,11]:mode==='practice'?questions.map((q,i)=>q.t===topic?i:-1).filter(i=>i>=0):questions.map((_,i)=>i);session={mode,ids,pos:0,answers:{},checked:{},started:Date.now(),deadline:mode==='test'?Date.now()+600000:null,finished:false};screen='quiz';setNav();renderQuiz();if(mode==='test')ticker=setInterval(updateTimer,500);window.scrollTo(0,0)}
function updateTimer(){if(!session||screen!=='quiz'||!session.deadline)return;const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000)),n=document.getElementById('timer');if(n){n.textContent=`◷ ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;n.classList.toggle('urgent',left<60)}if(!left)finish(true)}
function renderQuiz(){persistAttempt();const s=session,id=s.ids[s.pos],q=questions[id],t=topics[q.t],checked=!!s.checked[id],chosen=s.answers[id],mode=s.mode==='test'?'Диагностика':s.mode==='demo'?'Демо для выступления':'Тренировка';app.innerHTML=`<div class="topline"><button class="back" onclick="leave(home)">← На главную</button><span class="pill">${mode}${s.name?' · '+esc(s.name):''}</span><span class="timer" id="timer">${s.deadline?'◷ 10:00':'Без таймера'}</span></div><div class="section-title"><h2>${t.short}</h2><p>Вопрос ${s.pos+1} из ${s.ids.length}</p></div><div class="progressbar"><div style="width:${(s.pos+1)/s.ids.length*100}%"></div></div><div class="quiz-grid"><aside class="context"><div class="eyebrow">Контекст / 0${q.t+1}</div><h2>${t.title}</h2><p>${t.intro}</p>${t.table}<p class="footnote">${t.note}</p></aside><section class="qcard"><div class="qmeta"><span>${q.level}</span><span>Один верный ответ · 1 балл</span></div><h2 id="question-title">${q.q}</h2><div class="options" role="group" aria-labelledby="question-title">${q.o.map((o,i)=>`<button class="option ${chosen===i?'selected':''} ${checked&&i===q.a?'correct':''} ${checked&&chosen===i&&i!==q.a?'wrong':''}" onclick="choose(${i})" aria-pressed="${chosen===i}" ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${o}${checked&&i===q.a?' ✓':''}</span></button>`).join('')}</div>${checked?`<div class="feedback ${chosen===q.a?'':'error'}" role="status"><strong>${chosen===q.a?'Верно. Вы связали данные с объяснением.':'Разберём ошибку'}</strong><p>${chosen!==q.a?esc(q.errors[chosen])+' ':''}${q.e}</p></div>`:''}<div class="qbottom"><button class="back" onclick="move(-1)" ${s.pos===0?'disabled':''}>← Назад</button>${s.mode!=='test'&&!checked?`<button class="btn primary" onclick="check()" ${chosen===undefined?'disabled':''}>Проверить ответ</button>`:`<button class="btn primary" onclick="${s.pos===s.ids.length-1?'requestFinish()':'move(1)'}">${s.pos===s.ids.length-1?'Показать результат':'Далее →'}</button>`}</div></section></div><div class="qnav" aria-label="Переход к вопросу">${s.ids.map((x,i)=>`<button class="dot ${s.answers[x]!==undefined?'done':''} ${i===s.pos?'current':''}" onclick="jump(${i})" aria-label="Вопрос ${i+1}${s.answers[x]!==undefined?', ответ выбран':''}" ${i===s.pos?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="small">${s.mode==='test'?'Ответы можно менять до завершения. Время и ответы сохраняются при переходе между вопросами.':'Выберите ответ и нажмите «Проверить». В итогах можно вернуться к ошибкам.'}</p>`;updateTimer()}
function choose(i){const id=session.ids[session.pos];if(session.checked[id])return;session.answers[id]=i;renderQuiz()}
function check(){const id=session.ids[session.pos];if(session.answers[id]===undefined)return;session.checked[id]=true;renderQuiz()}
function move(d){jump(session.pos+d)}
function jump(pos){if(pos<0||pos>=session.ids.length)return;session.pos=pos;renderQuiz()}
function requestFinish(){const n=session.ids.filter(i=>session.answers[i]===undefined).length;if(n&&!confirm(`Без ответа: ${n}. Завершить попытку?`))return;finish(false)}
function finish(expired=false){stop();session.finished=true;session.expired=expired;session.elapsed=Math.min(session.deadline?(session.durationSeconds||600):Infinity,Math.floor((Date.now()-session.started)/1000));screen='results';persistAttempt();renderResult();if(session.remote&&!session.saved)saveAttempt();window.scrollTo(0,0)}
function summary(){const s=session;return {total:s.ids.length,score:s.ids.filter(i=>s.answers[i]===questions[i].a).length,stats:topics.map((t,k)=>{const ids=s.ids.filter(i=>questions[i].t===k);return {t,k,n:ids.length,correct:ids.filter(i=>s.answers[i]===questions[i].a).length}}).filter(x=>x.n)}}
function renderResult(){const r=summary(),wrong=session.ids.filter(i=>session.answers[i]!==questions[i].a);app.innerHTML=`<div class="topline"><button class="back" onclick="home()">← На главную</button><span class="pill">${session.mode==='test'?'Диагностика':session.mode==='demo'?'Демонстрация':'Тренировка'} завершена</span></div><section class="result-hero"><div class="score"><b>${r.score}/${r.total}</b><span>верных ответов</span></div><div><div class="eyebrow">От результата — к следующему шагу</div><p class="student-name">${esc(session.name||'Ученик')}${session.remote?' · '+esc(session.remote.roomTitle):''}</p><h1>${r.score===r.total?'Отличная работа!':'Теперь понятно, что повторить.'}</h1><p>${session.expired?'Время вышло. ':''}Время: ${Math.floor(session.elapsed/60)} мин ${session.elapsed%60} с. ${session.mode==='demo'?'Демо показывает работу тренажёра; четырёх вопросов недостаточно для оценки всей подготовки.':'Результат этой попытки — ориентир для повторения, не оценка МОДО.'}</p></div></section><div id="save-status" class="save-status" role="status"></div><div class="method-grid"><section class="panel"><h2>Карта результатов</h2>${r.stats.map(x=>`<div class="topic-row"><span>${x.t.short}</span><b>${x.correct}/${x.n}</b></div><div class="bar"><div style="width:${100*x.correct/x.n}%"></div></div>`).join('')}<p class="small">Верные ответы / выполненный набор заданий по теме.</p></section><section class="panel"><h2>Что делать дальше</h2>${r.stats.filter(x=>x.correct<x.n).length?r.stats.filter(x=>x.correct<x.n).map(x=>`<p><strong>${x.t.short}.</strong> ${x.t.tip}</p>`).join(''):'<p>Все ответы верны. Объясните выбор своими словами и пройдите другие тематические маршруты.</p>'}<div class="actions">${wrong.length?'<button class="btn primary" onclick="retry()">Работа над ошибками →</button>':''}<button class="btn secondary" onclick="downloadResult()">Скачать результат</button></div></section><section class="panel full"><h2>Разбор каждого задания</h2><div class="review">${session.ids.map((id,n)=>{const q=questions[id],v=session.answers[id],ok=v===q.a;return `<details><summary><span class="${ok?'ok':'err'}">${ok?'✓':'○'}</span> ${n+1}. ${q.q}</summary><p>Ваш ответ: <strong>${v===undefined?'Нет ответа':q.o[v]}</strong></p><p>Верный ответ: <strong>${q.o[q.a]}</strong></p><p>${!ok&&v!==undefined?q.errors[v]+' ':''}${q.e}</p></details>`}).join('')}</div></section></div><div class="actions" style="margin-top:25px"><button class="btn secondary" onclick="start('test')">Новая диагностика</button><button class="btn secondary" onclick="method()">Как показать это на выступлении →</button></div>`;renderSaveStatus()}
function retry(){if(session.remote&&!session.saved){toast('Дождитесь сохранения результата или повторите отправку.');return}const studentName=session.name;const ids=session.ids.filter(i=>session.answers[i]!==questions[i].a);session={name:studentName,mode:'practice',ids,pos:0,answers:{},checked:{},started:Date.now(),deadline:null,finished:false};screen='quiz';renderQuiz();window.scrollTo(0,0)}
function downloadResult(){const r=summary();const text=`Химия в контексте — результат учебной попытки\nУченик: ${session.name||'Без имени'}\n${new Date().toLocaleString('ru-RU')}\nВерных ответов: ${r.score} из ${r.total}\n${r.stats.map(x=>`${x.t.name}: ${x.correct}/${x.n}`).join('\n')}\n\n${session.ids.map((id,n)=>{const q=questions[id],v=session.answers[id];return `${n+1}. ${q.q}\nВаш ответ: ${v===undefined?'Нет ответа':q.o[v]}\nВерный ответ: ${q.o[q.a]}\nОбъяснение: ${q.e}`}).join('\n\n')}\n\nАвторские учебные задания. Результат не является официальной оценкой МОДО.`;const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Результат_тренажёра_МОДО.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function method(){stop();screen='method';setNav(true);app.innerHTML=`<section class="method-head"><div class="eyebrow">Материал для учителя</div><h1>Практика подготовки к МОДО с использованием цифровых инструментов и искусственного интеллекта</h1><p>Покажите весь цикл: затруднение → задание → ответ → обратная связь → адресная тренировка.</p><button class="btn primary" onclick="start('demo')">Запустить демо из 4 вопросов →</button></section><div class="method-grid"><section class="panel"><span class="tag">01 / ОБОСНОВАНИЕ</span><h2>Почему выбраны эти темы</h2><p>В предоставленном фрагменте ИМП, раздел «Химия» (с. 53 и следующая страница), обозначены направления устранения дефицитов:</p><ul><li>Теория электролитической диссоциации и периодический закон.</li><li>Зависимость свойств веществ от их строения.</li><li>Влияние веществ на здоровье и окружающую среду.</li></ul><p>В тренажёре первое направление разделено на два тематических маршрута. Год тестирования и проценты результатов не используются.</p></section><section class="panel"><span class="tag">02 / СЦЕНАРИЙ ПОКАЗА</span><h2>Демонстрация за 5–7 минут</h2><ol><li><strong>Обозначьте проблему:</strong> ученик знает термин, но затрудняется применить его в ситуации.</li><li><strong>Запустите демо:</strong> предложите аудитории прочитать таблицу и выбрать ответ.</li><li><strong>Покажите ошибку:</strong> обсудите, какое рассуждение к ней привело.</li><li><strong>Откройте итог:</strong> объясните переход к тематической тренировке.</li><li><strong>Покажите запрос к ИИ:</strong> обсудите проверку нового задания учителем.</li></ol></section><section class="panel full"><span class="tag">03 / ПАСПОРТ ЗАДАНИЙ</span><h2>От цели обучения к контексту</h2><div style="overflow-x:auto"><table><thead><tr><th>Маршрут</th><th>Цель и содержание</th><th>Контекст</th><th>Вопросы</th></tr></thead><tbody>${topics.map((t,i)=>`<tr><td>${t.name}</td><td>${t.goal}<br><span class="small">${t.code}</span></td><td>${t.title}</td><td>${i*3+1}–${i*3+3}</td></tr>`).join('')}</tbody></table></div><p class="small" style="margin:15px 0 0">Структура: цель обучения → контекст и данные → вопрос → четыре варианта, один верный ответ. Основание — предоставленные изображения спецификации и образцов заданий сайта <a href="https://taldau.edu.kz" target="_blank" rel="noopener noreferrer">taldau.edu.kz</a>. Контексты и формулировки авторские; таймер и состав диагностического набора — методический выбор для демонстрации.</p></section><section class="panel"><span class="tag">04 / ИИ В РАБОТЕ УЧИТЕЛЯ</span><h2>Подготовьте новый вариант</h2><p>Выберите тему и скопируйте запрос в доступный вам ИИ-сервис. Здесь показан шаблон запроса; живой ИИ к тренажёру не подключён.</p><label for="prompt-topic" class="small">Тема задания</label><select class="select" id="prompt-topic" onchange="updatePrompt()">${topics.map((t,i)=>`<option value="${i}">${t.name}</option>`).join('')}</select><label for="prompt-text" class="small">Запрос можно отредактировать</label><textarea id="prompt-text" class="prompt"></textarea><button class="btn primary" onclick="copyPrompt()">Скопировать запрос</button></section><section class="panel"><span class="tag">05 / ПРОВЕРКА УЧИТЕЛЕМ</span><h2>Перед использованием задания</h2><ul><li>Сопоставить тему и умение с действующей спецификацией.</li><li>Проверить формулы, уравнения, единицы и вычисления.</li><li>Убедиться, что верный ответ один, а условие достаточно для решения.</li><li>Проверить, что неверные варианты отражают реальные ошибки.</li><li>Отделить учебные модельные данные от реальных измерений.</li><li>Убедиться, что объяснение помогает исправить ошибку.</li></ul><p>Обратная связь и рекомендации в этом тренажёре подготовлены заранее. При повторном прохождении меняются ответы ученика, но не набор вопросов.</p></section><section class="panel full"><span class="tag">ИСТОЧНИКИ И ГРАНИЦЫ ПРИМЕНЕНИЯ</span><p style="margin:12px 0 0">Использованы предоставленные пользователем фрагмент ИМП «Химия», таблица спецификации и изображения образцов сайта <a href="https://taldau.edu.kz" target="_blank" rel="noopener noreferrer">taldau.edu.kz</a>. Полные редакции документов не сверены. Это демонстрационный авторский тренажёр, не официальный тест. При входе по коду занятия имя и ответы сохраняются для учителя этого занятия. Ученик видит только свой результат. Без кода доступна самостоятельная практика; она не попадает в кабинет учителя. Незавершённая попытка восстанавливается в той же вкладке. Итог можно скачать после завершения.</p></section></div>`;updatePrompt();window.scrollTo(0,0)}
function updatePrompt(){const t=topics[Number(document.getElementById('prompt-topic').value)];document.getElementById('prompt-text').value=`Создай авторское контекстное задание по химии для 9 класса для подготовки к МОДО. Тема: «${t.name}». Проверяемое умение: ${t.goal}\n\nИспользуй только приложенный мной фрагмент действующей спецификации для подтверждения цели обучения. Если фрагмент не приложен, не утверждай соответствие официальной спецификации.\n\nСтруктура: 1) цель обучения; 2) короткая жизненная ситуация; 3) таблица с достаточными для решения данными; 4) один вопрос на применение или анализ; 5) четыре варианта ответа, ровно один верный; 6) ключ с объяснением; 7) объяснение типичной ошибки для каждого неверного варианта.\n\nПроверь химические формулы, уравнения, единицы и расчёты. Модельные данные подпиши как учебные. Не приписывай заданию статус официального вопроса МОДО и не придумывай статистику ИМП. Отдельно перечисли, что должен проверить учитель.`}
async function copyPrompt(){const field=document.getElementById('prompt-text');try{await navigator.clipboard.writeText(field.value);toast('Запрос скопирован')}catch{field.select();toast('Выделен текст запроса. Нажмите Ctrl+C или «Копировать».')}}

async function api(op,data=null,token=null){const headers={};if(token)headers['X-Attempt-Token']=token;let url='/api/classroom?op='+encodeURIComponent(op);if(data&&data.query){url+='&'+new URLSearchParams(data.query);data=null}const options={method:data?'POST':'GET',headers,cache:'no-store'};if(data){headers['Content-Type']='application/json';options.body=JSON.stringify({op,...data})}const r=await fetch(url,options);let result;try{result=await r.json()}catch{throw new Error('Сервер недоступен. Попробуйте ещё раз.')}if(!r.ok)throw new Error(result.error||'Не удалось выполнить запрос');return result}
function persistAttempt(){if(!session)return;try{sessionStorage.setItem('modo-attempt-v2',JSON.stringify(session))}catch{}}
function savedAttempt(){try{const s=JSON.parse(sessionStorage.getItem('modo-attempt-v2')||'null');if(!s||!Array.isArray(s.ids)||!s.ids.length||s.ids.length>12||s.ids.some(i=>!Number.isInteger(i)||i<0||i>=questions.length)||!s.answers||!s.checked||!['test','practice','demo'].includes(s.mode)||!Number.isInteger(s.pos)||s.pos<0||s.pos>=s.ids.length)return null;return s}catch{return null}}
function start(mode,topic){const pending=savedAttempt();if(pending?.remote&&pending.finished&&!pending.saved){resume();toast('Сначала отправьте предыдущий результат учителю.');return}stop();screen='entry';setNav();const join=new URLSearchParams(location.search).get('join')||'';app.innerHTML=`<button class="back" onclick="home()">← На главную</button><section class="entry panel"><div class="eyebrow">${mode==='test'?'Работа по коду занятия':'Учебная практика'}</div><h1>Как вас зовут?</h1><p>Результат будет подписан вашим именем. ${mode==='test'?'Введите код занятия: откроются только вопросы выбранной учителем темы.':'Эта практика не отправляется в статистику класса.'}</p><form id="student-form"><label for="student-name">Имя и фамилия <span class="small">или обозначение, согласованное с учителем</span></label><input class="field" id="student-name" name="student-name" autocomplete="name" minlength="2" maxlength="80" required placeholder="Например, Алия К.">${mode==='test'?`<label for="room-code">Код занятия</label><input class="field code-input" id="room-code" autocomplete="off" maxlength="8" minlength="8" required value="${esc(join.toUpperCase())}" placeholder="8 символов от учителя" oninput="lookupWork()"><div id="work-info" class="work-info" role="status"></div><label class="checkline"><input type="checkbox" id="solo" onchange="document.getElementById('room-code').disabled=this.checked;document.getElementById('room-code').required=!this.checked;lookupWork()"> Самостоятельно, без отправки учителю</label>`:''}<p class="small">${mode==='test'?'При входе по коду имя, ответы и результат доступны учителю этого занятия.':'Проверка ответа и объяснение доступны после каждого вопроса.'}</p><p id="entry-error" class="form-error" role="alert"></p><button class="btn primary" id="student-submit" type="submit">Начать →</button></form></section>`;document.getElementById('student-form').onsubmit=async e=>{e.preventDefault();const name=document.getElementById('student-name').value.trim().replace(/\s+/g,' ');if(name.length<2)return;const button=document.getElementById('student-submit'),error=document.getElementById('entry-error');button.disabled=true;error.textContent='';let remote=null;try{if(mode==='test'&&!document.getElementById('solo').checked){const c=document.getElementById('room-code').value.trim().toUpperCase();remote=await api('start',{name,code:c});remote.code=c}launchSession(mode,topic);session.name=name;if(remote){session.remote=remote;session.started=remote.startedAt;session.deadline=remote.deadline;session.ids=remote.questionIds;session.durationSeconds=remote.durationSeconds;session.topic=remote.topic}persistAttempt();renderQuiz()}catch(err){if(screen==='entry'){error.textContent=err.message;button.disabled=false}}};window.scrollTo(0,0);document.getElementById('student-name').focus();if(mode==='test'&&join)lookupWork()}
function renderSaveStatus(){const n=document.getElementById('save-status');if(!n)return;if(!session.remote){n.innerHTML='Самостоятельная практика: результат не отправлялся учителю.';return}n.innerHTML=session.saved?'✓ Результат сохранён. Учитель видит ваше имя, баллы и ответы.':session.saveError?`<span>Результат пока не отправлен: ${esc(session.saveError)}</span> <button class="btn secondary" onclick="saveAttempt()">Отправить ещё раз</button>`:'Сохраняем результат для учителя… Не закрывайте вкладку.';n.classList.toggle('save-error',!!session.saveError)}
async function saveAttempt(){const target=session;if(!target.remote||target.saved||target.saving)return;target.saving=true;delete target.saveError;renderSaveStatus();try{const answerList=questions.map((_,i)=>target.answers[i]??null);const result=await api('finish',{id:target.remote.id,answers:answerList},target.remote.token);target.saved=!!result.saved;target.serverScore=result.score;result.answers.forEach((v,i)=>{if(v===null)delete target.answers[i];else target.answers[i]=v});if(target===session){persistAttempt();if(screen==='results')renderResult()}}catch(e){target.saveError=e.message;if(target===session){persistAttempt();renderSaveStatus()}}finally{target.saving=false;if(target===session)persistAttempt()}}
function resume(){const s=savedAttempt();if(!s)return home();session=s;session.saving=false;setNav();if(s.finished){screen='results';renderResult();if(s.remote&&!s.saved)saveAttempt()}else{screen='quiz';renderQuiz();if(session.deadline&&!session.finished)ticker=setInterval(updateTimer,500)}}
const originalHome=home;home=function(){originalHome();const s=savedAttempt();if(s){const box=document.createElement('div');box.className='resume-banner';box.innerHTML=`<span>${s.finished?'Последний результат':'Незавершённая попытка'}: <strong>${esc(s.name||'Ученик')}</strong></span><button class="btn secondary" onclick="resume()">${s.finished?'Открыть результат':'Продолжить'}</button>`;app.prepend(box)}};
document.getElementById('nav-teacher').onclick=()=>leave(teacher);
function teacherNav(){setNav();document.getElementById('nav-home').classList.remove('active');document.getElementById('nav-teacher').classList.add('active')}
async function teacher(){stop();screen='teacher';teacherNav();app.innerHTML='<p>Загружаем кабинет учителя…</p>';try{const me=await api('me');if(screen!=='teacher')return;if(!me.signedIn){renderTeacherLogin(me.configured);return}const data=await api('rooms');if(screen!=='teacher')return;app.innerHTML=`<div class="method-head"><div class="eyebrow">Кабинет учителя</div><h1>От ошибок — к работе с классом</h1><p>Создайте занятие и передайте ученикам код, ссылку или QR-код. Завершённые попытки появятся в статистике с именами.</p><div class="actions"><button class="btn secondary" onclick="showQR()">QR-код приложения</button><button class="btn secondary" onclick="teacherLogout()">Выйти из кабинета</button></div></div><section class="panel"><form id="create-room" class="create-form"><div><label for="room-title">Название занятия или класс</label><input id="room-title" class="field" maxlength="100" minlength="2" required placeholder="Например, 9А · Подготовка к МОДО"></div><div class="topic-setting"><label for="work-topic">Тема работы</label><select id="work-topic" class="select" onchange="updateWorkDefaults()">${topics.map((t,i)=>`<option value="${i}">${t.name}</option>`).join('')}<option value="-1">Все темы · 12 вопросов</option></select></div><div class="time-setting"><label for="work-minutes">Время, минут</label><input id="work-minutes" class="field" type="number" min="1" max="60" step="1" value="3" required></div><button type="submit" id="create-button" class="btn primary">Создать работу →</button></form><p class="small" id="work-summary">Одна тема · 3 вопроса · отдельный код и QR-код.</p><p id="create-error" class="form-error" role="alert"></p></section><div class="section-title"><h2>Ваши занятия</h2><button class="btn secondary" onclick="teacher()">Обновить</button></div><div class="room-list">${data.rooms.length?data.rooms.map(r=>`<button class="room-card" onclick="report('${r.id}')"><div><span class="tag">${r.active?'ВХОД ОТКРЫТ':'ВХОД ЗАКРЫТ'}</span><h3>${esc(r.title)}</h3><p class="small" style="margin:0">${esc(workTopicName(r.topic))} · вопросов: ${r.topic===-1?12:3} · ${Math.round((r.duration_seconds||600)/60)} мин</p><span class="small">Код ${esc(r.code)} · ${new Date(r.created_at).toLocaleDateString('ru-RU')}</span></div><div><b>${r.completed}</b><span class="small">завершено · ${r.started} в работе</span></div><span>→</span></button>`).join(''):'<div class="empty"><h3>Пока нет занятий</h3><p>Создайте первое занятие. Данные появятся после входа учеников по коду.</p></div>'}</div>`;document.getElementById('create-room').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('create-button');b.disabled=true;try{const r=await api('create',{title:document.getElementById('room-title').value,topic:Number(document.getElementById('work-topic').value),durationSeconds:Number(document.getElementById('work-minutes').value)*60});report(r.id)}catch(err){document.getElementById('create-error').textContent=err.message;b.disabled=false}}}catch(e){if(screen==='teacher')app.innerHTML=`<section class="panel"><h2>Не удалось загрузить кабинет</h2><p>${esc(e.message)}</p><button class="btn" onclick="teacher()">Повторить</button></section>`}window.scrollTo(0,0)}
async function report(id,refresh=false){if(!refresh){stop();reportTarget=id;screen='report';teacherNav();currentReport=null;reportFilter='';reportOnlyErrors=false;app.innerHTML='<p>Загружаем результаты занятия…</p>'}try{const data=await api('report',{query:{room:id}});if(screen!=='report'||reportTarget!==id)return;currentReport=data;renderReport();if(!teacherPoll)teacherPoll=setInterval(()=>{if(screen==='report')report(id,true)},15000)}catch(e){if(screen!=='report')return;if(refresh){const n=document.getElementById('refresh-status');if(n)n.textContent='Не удалось обновить. Проверьте соединение.'}else app.innerHTML=`<section class="panel"><h2>Результаты недоступны</h2><p>${esc(e.message)}</p><button class="btn" onclick="report('${id}')">Повторить</button><button class="btn secondary" onclick="teacher()">К занятиям</button></section>`}}
function renderReport(){const {room,attempts,stats}=currentReport,ids=room.questionIds||questions.map((_,i)=>i),done=attempts.filter(a=>a.finished_at!==null),avg=done.length?(done.reduce((s,a)=>s+a.score,0)/done.length).toFixed(1):'—',link=location.origin+'/?join='+room.code;const openQuestionId=document.getElementById('question-detail')?.dataset.question;const openAttemptId=document.getElementById('attempt-detail')?.dataset.attempt;app.innerHTML=`<div class="topline"><button class="back" onclick="teacher()">← Все занятия</button><span class="small" id="refresh-status">Обновлено ${new Date().toLocaleTimeString('ru-RU')} · автообновление 15 с</span></div><div class="method-head"><div class="eyebrow">Статистика занятия</div><h1>${esc(room.title)}</h1><div class="pills"><span class="pill">${esc(workTopicName(room.topic))}</span><span class="pill">Вопросов: ${ids.length}</span><span class="pill">${Math.round((room.durationSeconds||600)/60)} мин</span></div><p>Имена, результаты и конкретные задания выбранной темы для повторения.</p></div><section class="share-panel"><div><span class="tag">КОД ДЛЯ УЧЕНИКОВ</span><div class="room-code">${esc(room.code)}</div><p>${room.active?'Вход в занятие открыт':'Вход для новых попыток закрыт'}</p></div><div class="share-actions"><label for="student-link">Ссылка на вход в занятие</label><input id="student-link" class="field" readonly value="${esc(link)}"><div class="actions"><button class="btn primary" onclick="copyJoinLink()">Копировать ссылку</button><button class="btn secondary" onclick="showQR(currentReport.room.code)">QR-код работы</button><button class="btn secondary" onclick="toggleRoom()">${room.active?'Закрыть вход':'Открыть вход'}</button></div></div></section><div class="metrics"><div><b>${done.length}</b><span>завершённых попыток</span></div><div><b>${attempts.length-done.length}</b><span>незавершённых попыток</span></div><div><b>${avg}<small> / ${ids.length}</small></b><span>средний балл</span></div><div><b>${stats.filter(x=>x.wrong+x.skipped>0).length}</b><span>вопросов для повторения</span></div></div><section class="panel"><div class="section-title" style="margin-top:0"><div><h2>Какие вопросы требуют работы</h2><p>Нажмите на вопрос, чтобы увидеть имена и ответы учеников.</p></div></div>${done.length?`<div class="question-stats">${[...stats].sort((a,b)=>(b.wrong+b.skipped)-(a.wrong+a.skipped)||a.question-b.question).map(s=>`<button class="question-stat" onclick="showQuestion(${s.question})"><div><b>Вопрос ${ids.indexOf(s.question-1)+1}</b><span>${esc(topics[questions[s.question-1].t].short)}</span></div><div class="bar"><div style="width:${100*(s.wrong+s.skipped)/done.length}%;background:${s.wrong+s.skipped?'var(--orange)':'var(--green)'}"></div></div><span class="small">Ошибки: ${s.wrong} · без ответа: ${s.skipped} · верно: ${s.correct}</span></button>`).join('')}</div>`:'<p>Пока нет завершённых попыток. После прохождения здесь появятся затруднения по вопросам.</p>'}<div id="question-detail"></div></section><section class="panel" style="margin-top:22px"><div class="section-title" style="margin-top:0"><h2>Именные результаты</h2><button class="btn secondary" onclick="downloadTeacherCSV()" ${done.length?'':'disabled'}>Скачать CSV</button></div><div class="filters"><input class="field" id="student-search" aria-label="Поиск ученика" placeholder="Найти ученика по имени" value="${esc(reportFilter)}" oninput="reportFilter=this.value;renderRows()"><label class="checkline"><input type="checkbox" ${reportOnlyErrors?'checked':''} onchange="reportOnlyErrors=this.checked;renderRows()"> Только с ошибками</label><button class="btn secondary" onclick="report('${room.id}',true)">Обновить</button></div><p class="small">Каждая строка — отдельная попытка. Повторные прохождения и одинаковые имена не объединяются. ✓ — верно; × — ошибка; — — нет ответа. Нажмите на имя для разбора.</p><div id="student-rows" class="table-scroll"></div><div id="attempt-detail"></div></section>`;renderRows();if(openQuestionId)showQuestion(Number(openQuestionId));if(openAttemptId)showAttempt(openAttemptId)}
function renderRows(){const ids=currentReport.room.questionIds;const rows=currentReport.attempts.filter(a=>a.name.toLocaleLowerCase('ru').includes(reportFilter.toLocaleLowerCase('ru'))&&(!reportOnlyErrors||(a.finished_at!==null&&a.score<ids.length)));document.getElementById('student-rows').innerHTML=rows.length?`<table class="results-table"><thead><tr><th>Ученик / попытка</th><th>Результат</th>${ids.map((id,i)=>`<th title="${esc(questions[id].q)}">${i+1}</th>`).join('')}<th>Нужно повторить</th></tr></thead><tbody>${rows.map(a=>{const wrong=a.answers?ids.map((id,i)=>a.answers[id]!==questions[id].a?i+1:0).filter(Boolean):[];return `<tr><td><button class="name-link" onclick="showAttempt('${a.id}')">${esc(a.name)}</button><br><span class="small">${new Date(a.started_at).toLocaleString('ru-RU')}</span></td><td><strong>${a.finished_at===null?'В работе':a.score+'/'+ids.length}</strong></td>${ids.map(id=>`<td class="${a.answers?(a.answers[id]===questions[id].a?'cell-ok':a.answers[id]===null?'cell-skip':'cell-wrong'):''}">${a.answers?(a.answers[id]===questions[id].a?'✓':a.answers[id]===null?'—':'×'):'·'}</td>`).join('')}<td>${a.answers?(wrong.length?'№ '+wrong.join(', '):'Всё верно'):'Ещё не завершено'}</td></tr>`}).join('')}</tbody></table>`:'<p class="empty">Результатов по этому фильтру пока нет.</p>'}
function showQuestion(n){const q=questions[n-1],node=document.getElementById('question-detail'),local=currentReport.room.questionIds.indexOf(n-1)+1;node.dataset.question=n;const rows=currentReport.attempts.filter(a=>a.finished_at!==null&&a.answers[n-1]!==q.a);node.innerHTML=`<div class="detail-box"><h3>Вопрос ${local}. ${q.q}</h3><p><strong>Правильный ответ:</strong> ${esc(q.o[q.a])}</p><p>${q.e}</p><h3>Кому нужна работа над вопросом</h3>${rows.length?`<ul class="error-names">${rows.map(a=>`<li><button class="name-link" onclick="showAttempt('${a.id}')">${esc(a.name)}</button> — ${a.answers[n-1]===null?'нет ответа':esc(q.o[a.answers[n-1]])}<span class="small"> · ${new Date(a.started_at).toLocaleString('ru-RU')}</span></li>`).join('')}</ul>`:'<p>В завершённых попытках все ответили верно.</p>'}<p><strong>Для повторения:</strong> ${topics[q.t].tip}</p></div>`}
function showAttempt(id){const a=currentReport.attempts.find(x=>x.id===id),node=document.getElementById('attempt-detail'),ids=currentReport.room.questionIds;if(!a)return;node.dataset.attempt=id;node.innerHTML=`<div class="detail-box"><h3>${esc(a.name)} · ${new Date(a.started_at).toLocaleString('ru-RU')}</h3>${a.answers?`<p>Результат: <strong>${a.score} из ${ids.length}</strong>. Время: ${Math.floor(a.elapsed/60)} мин ${a.elapsed%60} с.</p><div class="review">${ids.map((id,i)=>{const q=questions[id];return `<details><summary>${a.answers[id]===q.a?'✓':'○'} Вопрос ${i+1}. ${q.q}</summary><p>Ответ ученика: <strong>${a.answers[id]===null?'Нет ответа':esc(q.o[a.answers[id]])}</strong></p><p>Верный ответ: <strong>${esc(q.o[q.a])}</strong></p><p>${q.e}</p></details>`}).join('')}</div>`:'<p>Ученик начал работу, но ещё не завершил попытку.</p>'}</div>`}
async function copyJoinLink(){const input=document.getElementById('student-link');try{await navigator.clipboard.writeText(input.value);toast('Ссылка для учеников скопирована')}catch{input.select();toast('Нажмите Ctrl+C или «Копировать».')}}
async function toggleRoom(){const r=currentReport.room;try{await api('close',{room:r.id,active:r.active?0:1});await report(r.id,true)}catch(e){toast(e.message)}}
function downloadTeacherCSV(){const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Ученик','Начало попытки','Балл','Всего','Время (с)',...currentReport.room.questionIds.map((id,i)=>'Вопрос '+(i+1)),'Вопросы для повторения'],...currentReport.attempts.filter(a=>a.finished_at!==null).map(a=>[a.name,new Date(a.started_at).toLocaleString('ru-RU'),a.score,currentReport.room.questionIds.length,a.elapsed,...currentReport.room.questionIds.map(i=>a.answers[i]===questions[i].a?'Верно':a.answers[i]===null?'Нет ответа':'Ошибка'),currentReport.room.questionIds.map((id,i)=>a.answers[id]!==questions[id].a?i+1:null).filter(Boolean).join(', ')])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='МОДО_результаты_класса.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function renderTeacherLogin(configured){app.innerHTML=`<section class="panel entry"><div class="eyebrow">Кабинет учителя</div><h1>Статистика вашего класса</h1><p>Введите пароль учителя, заданный при настройке приложения. Ученикам для работы пароль не нужен.</p>${configured?'': '<p class="form-error">Вход ещё не настроен. Администратору нужно указать DATABASE_URL, TEACHER_PASSWORD и AUTH_SECRET в Vercel и подготовить базу по README.</p>'}<form id="teacher-login"><label for="teacher-password">Пароль учителя</label><input class="field" id="teacher-password" type="password" autocomplete="current-password" required maxlength="256"><p class="form-error" id="login-error" role="alert"></p><button id="login-button" class="btn primary" ${configured?'':'disabled'}>Войти</button></form></section>`;document.getElementById('teacher-login').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('login-button');b.disabled=true;try{await api('login',{password:document.getElementById('teacher-password').value});await teacher()}catch(err){document.getElementById('login-error').textContent=err.message;b.disabled=false}}}
async function teacherLogout(){try{await api('logout',{});currentReport=null;await teacher()}catch(e){toast(e.message)}}


function workTopicName(t){return topics[t]?.name||'Все темы'}
function updateWorkDefaults(){const t=Number(document.getElementById('work-topic').value);document.getElementById('work-minutes').value=t===-1?10:3;document.getElementById('work-summary').textContent=t===-1?'Все темы · 12 вопросов · отдельный код и QR-код.':'Одна тема · 3 вопроса · отдельный код и QR-код.'}
async function lookupWork(){const input=document.getElementById('room-code'),info=document.getElementById('work-info');if(!input||!info)return;const c=input.value.trim().toUpperCase();if(input.disabled){info.textContent='Самостоятельная диагностика: все темы, 12 вопросов, 10 минут.';return}if(c.length!==8){info.textContent='';return}info.textContent='Проверяем код…';try{const work=await api('join',{query:{code:c}});if(screen!=='entry'||input.value.trim().toUpperCase()!==c)return;info.innerHTML=`<strong>${esc(work.roomTitle)}</strong><br>${esc(work.topicTitle)} · вопросов: ${work.questionIds.length} · ${Math.round(work.durationSeconds/60)} мин`;}catch(e){if(screen==='entry'&&input.value.trim().toUpperCase()===c)info.textContent=e.message}}
async function showQR(code=''){try{if(!window.modoQR){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/qr.js';script.onload=resolve;script.onerror=reject;document.body.appendChild(script)})}const url=location.origin+'/'+(code?'?join='+encodeURIComponent(code):'');const data=window.modoQR(url);let dialog=document.getElementById('qr-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='qr-dialog';dialog.className='install-dialog';document.body.appendChild(dialog)}dialog.innerHTML=`<form method="dialog"><button class="dialog-close" aria-label="Закрыть">×</button></form><h2>${code?'Вход в тематическую работу':'Химия МОДО'}</h2><p>${code?'Сканируйте QR-код и введите имя. Откроется только выбранная учителем работа.':'Сканируйте QR-код для открытия приложения.'}</p><img src="${data}" alt="QR-код" style="display:block;width:100%;max-width:400px;margin:auto">${code?'<p style="text-align:center;font-weight:bold">Код: '+esc(code)+'</p>':''}<a class="btn primary link-btn" download="QR_Himiya_MODO.png" href="${data}">Скачать QR-код</a>`;dialog.showModal()}catch{toast('Не удалось создать QR-код. Проверьте соединение.')}}

const params=new URLSearchParams(location.search);if(params.has('teacher'))teacher();else if(params.has('join')){const s=savedAttempt();if(s&&!s.finished&&s.remote&&s.remote.code===params.get('join')?.toUpperCase())resume();else start('test')}else home();
